 public class Transform{public GameObject gameObject;public string name=>gameObject.name;public Quaternion localRotation=Quaternion.identity;public readonly List<Transform> children=new List<Transform>();public BoxCollider collider;public Transform(GameObject o){gameObject=o;}public T GetComponent<T>() where T:class{return collider as T;}public T[] GetComponentsInChildren<T>(bool all) where T:class{var list=new List<T>();if(this is T)list.Add(this as T);foreach(var c in children)list.AddRange(c.GetComponentsInChildren<T>(all));return list.ToArray();}}
