 static void A(bool yes,string msg){if(!yes)throw new Exception(msg);}static Transform Child(Transform p,string n){var t=new GameObject(n).transform;p.children.Add(t);return t;}
 static EntityVehicle Build(out Transform roof,out Transform inside,out Transform walk,out Transform door,out Transform rails){var root=new GameObject("rebirthCamper80s").transform;var model=Child(root,"GameObject");model.collider=new BoxCollider();var physics=Child(root,"Physics");Child(physics,"CabHull").collider=new BoxCollider();Child(physics,"CamperHull").collider=new BoxCollider();walk=Child(physics,"REBIRTHCampWalkInColliders");walk.gameObject.SetActive(false);var vis=Child(Child(model,"M"),"VisualBody");roof=Child(vis,"REBIRTHCampRoofStations");inside=Child(vis,"REBIRTHCampInteriorStations");roof.gameObject.SetActive(false);inside.gameObject.SetActive(false);rails=Child(vis,"Fitted rooftop guardrails");door=Child(vis,"REBIRTHRearDoorPivot");door.collider=new BoxCollider{enabled=false};Child(vis,"REBIRTHRearDoorOpenPose").localRotation=Quaternion.Euler(0,-110,0);return new EntityVehicle{RootTransform=root,ModelTransform=model};}
