 static void Main(){var v=Build(out var roof,out var inside,out var walk,out var door,out var rails);Tick(v,RebirthCamperEnergyMode.Travel);A(!roof.gameObject.activeSelf&&!inside.gameObject.activeSelf&&!walk.gameObject.activeSelf&&door.localRotation.y==0&&v.ModelTransform.collider.enabled,"Travel default");Tick(v,RebirthCamperEnergyMode.Camp);A(roof.gameObject.activeSelf&&inside.gameObject.activeSelf&&walk.gameObject.activeSelf&&door.localRotation.y==-110&&door.collider.enabled&&!v.ModelTransform.collider.enabled,"Camp presentation and hull");A(rails.gameObject.activeSelf,"Camp rails");v.ModelTransform.collider.enabled=true;RebirthCamperCampStationAppearance.Update(v);A(!v.ModelTransform.collider.enabled,"Reassert after native physics refresh");foreach(var m in new[]{RebirthCamperEnergyMode.Packing,RebirthCamperEnergyMode.Deploying,RebirthCamperEnergyMode.Travel}){Tick(v,m);A(!roof.gameObject.activeSelf&&!walk.gameObject.activeSelf&&door.localRotation.y==0&&!door.collider.enabled&&v.ModelTransform.collider.enabled&&rails.gameObject.activeSelf,"Hide and close outside Camp");Tick(v,RebirthCamperEnergyMode.Camp);}Tick(v,RebirthCamperEnergyMode.Camp,false);A(!roof.gameObject.activeSelf&&door.localRotation.y==0,"Unknown state safe default");Tick(v,RebirthCamperEnergyMode.Travel);v.ModelTransform.collider.enabled=false;RebirthCamperCampStationAppearance.Update(v);A(!v.ModelTransform.collider.enabled,"Do not override native Travel collider lifecycle");var replacement=Build(out roof,out inside,out walk,out door,out rails);v.RootTransform=replacement.RootTransform;v.ModelTransform=replacement.ModelTransform;Tick(v,RebirthCamperEnergyMode.Camp);A(roof.gameObject.activeSelf&&door.localRotation.y==-110,"Model replacement rebind");Console.WriteLine("PASS actual appearance source: Travel/Camp/Deploying/Packing/unknown, door pose, shell/hull toggles, guardrail preservation, native collider refresh, Travel lifecycle, model replacement. Unity/entity/mode adapters doubled; no gameplay test.");}
